CREATE TYPE public.app_role AS ENUM ('worker', 'employer');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated;
GRANT UPDATE (display_name, avatar_url) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own profile" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY "Update own profile" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.employer_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, expires_at timestamptz NOT NULL DEFAULT (now() + interval '7 days'), accepted_by uuid REFERENCES public.profiles(id), accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.employer_invitations TO service_role;
ALTER TABLE public.employer_invitations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.employee_links (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, employee_reference text NOT NULL UNIQUE, employer_user_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.employee_links TO authenticated;
GRANT ALL ON public.employee_links TO service_role;
ALTER TABLE public.employee_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own employment link" ON public.employee_links FOR SELECT TO authenticated USING (user_id = auth.uid() OR (employer_user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'employer')));
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, display_name) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'full_name', '')); INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'worker'); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_account_profile() FROM PUBLIC;
CREATE TRIGGER create_account_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();
CREATE FUNCTION public.accept_employer_invitation() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE caller_email text; invitation_id uuid; BEGIN SELECT lower(email) INTO caller_email FROM auth.users WHERE id = auth.uid() AND email_confirmed_at IS NOT NULL; IF caller_email IS NULL THEN RETURN false; END IF; SELECT id INTO invitation_id FROM public.employer_invitations WHERE lower(email) = caller_email AND accepted_by IS NULL AND expires_at > now() FOR UPDATE; IF invitation_id IS NULL THEN RETURN false; END IF; INSERT INTO public.user_roles(user_id, role) VALUES(auth.uid(), 'employer') ON CONFLICT DO NOTHING; UPDATE public.employer_invitations SET accepted_by = auth.uid(), accepted_at = now() WHERE id = invitation_id; RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.accept_employer_invitation() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.accept_employer_invitation() TO authenticated;
INSERT INTO public.profiles(id, display_name) SELECT id, coalesce(raw_user_meta_data->>'display_name', '') FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id, role) SELECT id, 'worker'::public.app_role FROM auth.users ON CONFLICT DO NOTHING;